// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }

    function testFuzz_property(address actor) public {
        vm.assume(actor != address(0));

        uint256 totalDist = c.totalDistributed();
        address ownerBefore = address(this);
        uint256 balBefore = c.balanceOf(ownerBefore);

        bool ok;
        try c.NETM{gas: gasleft()}() {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.balanceOf(ownerBefore) == c.totalDistributed());
        } else {
            assertTrue(c.balanceOf(ownerBefore) == balBefore);
        }
    }
}
